import{_ as e,o as a,c as d,a5 as r}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"集成电路产业链","description":"理解设计、EDA、IP、制造、封测与设备材料的分工，认识中国大陆和上海产业生态。","frontmatter":{"title":"集成电路产业链","description":"理解设计、EDA、IP、制造、封测与设备材料的分工，认识中国大陆和上海产业生态。"},"headers":[],"relativePath":"explore-ic/industry-chain.md","filePath":"explore-ic/industry-chain.md","lastUpdated":1795531638000}'),i={name:"explore-ic/industry-chain.md"};function n(h,t,o,l,s,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="集成电路产业链" tabindex="-1">集成电路产业链 <a class="header-anchor" href="#集成电路产业链" aria-label="Permalink to &quot;集成电路产业链&quot;">​</a></h1><p>一颗芯片不是一家设计公司的独立作品。它通常需要设计软件、可复用模块、晶圆工艺、生产设备、材料、封装与测试共同支持。理解产业链，首先要分清“谁交付什么”，而不是先背公司排名。</p><h2 id="从需求到产品的分工" tabindex="-1">从需求到产品的分工 <a class="header-anchor" href="#从需求到产品的分工" aria-label="Permalink to &quot;从需求到产品的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>主要交付物</th><th>与相邻环节的接口</th></tr></thead><tbody><tr><td>芯片设计</td><td>规格、架构、逻辑与版图数据</td><td>依赖工艺模型、EDA 和 IP，向制造端交付签核数据</td></tr><tr><td>电子设计自动化（Electronic Design Automation，EDA）</td><td>仿真、验证、综合、布局布线等软件</td><td>把设计意图转成可检查、可制造的实现</td></tr><tr><td>半导体知识产权核（Intellectual Property，IP）</td><td>处理器核、接口、存储器宏等可复用模块</td><td>通过接口、时序、物理和授权条件嵌入设计</td></tr><tr><td>晶圆制造</td><td>在晶圆上形成器件和互连</td><td>提供工艺设计套件，按制造规则生产</td></tr><tr><td>封装与测试</td><td>可安装、散热、互连且经过筛选的产品</td><td>把裸片接入系统，并筛除不合格产品</td></tr><tr><td>设备与材料</td><td>光刻、刻蚀、沉积、检测设备及材料</td><td>为制造、封装和测试提供稳定的生产能力</td></tr></tbody></table><p>这里的“IP”不是网络地址。工艺设计套件（Process Design Kit，PDK）则包含器件模型、设计规则等信息，使设计软件能够针对特定工艺工作。工具、PDK 与设计数据库之间存在版本和授权约束；拿到软件并不等于拿到了可流片的工艺环境。</p><h2 id="三种常见经营模式" tabindex="-1">三种常见经营模式 <a class="header-anchor" href="#三种常见经营模式" aria-label="Permalink to &quot;三种常见经营模式&quot;">​</a></h2><ul><li><strong>无晶圆厂设计公司（Fabless）</strong>：主要负责产品定义与设计，委托其他企业制造、封测。</li><li><strong>晶圆代工厂（Foundry）</strong>：主要向客户提供制造工艺与产能，但服务范围也可能延伸到 IP、设计支持和封装。</li><li><strong>垂直整合制造商（Integrated Device Manufacturer，IDM）</strong>：同时拥有芯片设计和制造等能力，也可能采购外部产能或对外提供服务。</li></ul><p>这些不是互斥的永久标签。公司可以横跨多个环节，企业并购和业务调整也会改变版图；封装同样不再只是最后“套个壳”，先进封装已经参与系统架构设计。</p><h2 id="国内外公司版图" tabindex="-1">国内外公司版图 <a class="header-anchor" href="#国内外公司版图" aria-label="Permalink to &quot;国内外公司版图&quot;">​</a></h2><p>以下仅列便于建立坐标的代表性企业，<strong>不作市占率、技术水平、招聘质量或投资排序</strong>。“中国大陆”与“其他地区”只是本表的观察口径，不代表所有权或供应链完全独立。</p><table tabindex="0"><thead><tr><th>环节</th><th>中国大陆企业举例</th><th>其他地区企业举例</th><th>阅读公司介绍时看什么</th></tr></thead><tbody><tr><td>数字与通信芯片设计</td><td>海思、紫光展锐、寒武纪</td><td>NVIDIA、AMD、Qualcomm、MediaTek</td><td>产品面向什么工作负载，是否依赖配套软件</td></tr><tr><td>模拟与功率芯片</td><td>圣邦股份、思瑞浦、韦尔股份</td><td>Texas Instruments、Analog Devices、Infineon</td><td>工艺、精度、电压、可靠性与应用领域</td></tr><tr><td>EDA</td><td>华大九天、概伦电子、广立微</td><td>Synopsys、Cadence、Siemens EDA</td><td>覆盖哪个流程，支持什么工艺与数据格式</td></tr><tr><td>IP</td><td>芯原股份、芯来科技</td><td>Arm、Synopsys、Cadence</td><td>授权的是架构、RTL、硬核还是服务</td></tr><tr><td>晶圆制造</td><td>中芯国际、华虹集团、长江存储</td><td>TSMC、Samsung、Intel、GlobalFoundries、Micron</td><td>逻辑、特色工艺与存储制造不能简单横比</td></tr><tr><td>封装测试</td><td>长电科技、通富微电、华天科技</td><td>ASE、Amkor</td><td>封装形态、互连密度、散热和测试能力</td></tr><tr><td>制造设备</td><td>中微公司、北方华创、盛美上海</td><td>ASML、Applied Materials、Lam Research、Tokyo Electron</td><td>具体是哪类设备、进入哪道工序</td></tr><tr><td>材料与晶圆</td><td>沪硅产业、安集科技、鼎龙股份</td><td>Shin-Etsu、SUMCO、JSR</td><td>硅片、光刻胶、抛光材料等不能混为一类</td></tr></tbody></table><p>其中长江存储主要是存储制造企业，不应当把它当成通用逻辑代工厂；Intel、Samsung 也不只属于某一个格子。更多公司入口、求职观察方法见 <a href="/shanghaitech-ic-wiki-dev.github.io/career/employment/companies">企业与产业</a>。</p><h2 id="中国大陆-看能力组合-不只看节点" tabindex="-1">中国大陆：看能力组合，不只看节点 <a class="header-anchor" href="#中国大陆-看能力组合-不只看节点" aria-label="Permalink to &quot;中国大陆：看能力组合，不只看节点&quot;">​</a></h2><p>中国大陆已经形成覆盖设计、制造、封测、设备材料及 EDA/IP 的产业参与者。不同产品对先进逻辑工艺、特色工艺、非易失存储、功率器件和先进封装的需求差别很大。讨论产业能力时，应拆成具体产品、具体工序和具体交付条件，而不是用一个“多少纳米”概括所有领域。</p><p>设备验证、材料一致性、生产良率、工具适配与客户认证都需要长期积累。实验室能做出器件，不代表已经形成稳定量产能力；有产品发布，也不等于所有上游环节都由同一地区提供。</p><h2 id="上海-张江与临港怎样看" tabindex="-1">上海：张江与临港怎样看 <a class="header-anchor" href="#上海-张江与临港怎样看" aria-label="Permalink to &quot;上海：张江与临港怎样看&quot;">​</a></h2><p>上海的集成电路生态横跨设计、制造、装备材料与封测。<strong>张江</strong>适合用来观察设计研发、制造、设备企业与科研机构之间的联系；<strong>临港</strong>则可以观察晶圆制造、装备材料和先进封装等产业项目的集聚。两者不是“一个只设计、一个只制造”的严格分区，也不是互相独立的供应链。</p><p>上海市政府公开报道指出，临港的集成电路产业链持续完善；市国资委关于长电汽车电子临港工厂的报道，也提供了封测环节在当地落地的具体例子。产业项目变化快，本文不据此推算实时产能、企业数量或岗位规模。</p><p>对上科大学生，更有价值的问题是：一次参访看到了哪道工序？一份实习岗位对应设计、验证还是生产测试？课程项目中的约束，在企业中由哪个团队负责？可结合 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">上科大产业与培养项目</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/career/internship/">实习准备</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/knowledge-map">设计流程</a> 继续阅读。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://www.shanghai.gov.cn/nw4411/20250819/1dd8011ee9e946f2b0228fb2a1fe1576.html" target="_blank" rel="noreferrer">上海市政府：临港新片区产业链发展报道（2025-08-19）</a>。</li><li><a href="https://www.gzw.sh.gov.cn/shgzw_zxzx_gqdt/20260311/aaec3dd6f1854b79bf164f6b655cbab2.html" target="_blank" rel="noreferrer">上海市国资委：长电汽车电子临港工厂投产（2026-03-11）</a>。</li><li><a href="https://www.shanghai.gov.cn/zhengce/detail?businessId=d65768a6b59b49c1a4d5c164f453cbb0&amp;siteId=0016" target="_blank" rel="noreferrer">上海市政府：张江高新区发展规划</a>：用于理解区域产业布局，不代表所有规划目标已实现。</li><li>企业名称用于产业分类举例，业务与招聘信息以各企业官网为准。</li></ul>',21)])])}const u=e(i,[["render",n]]);export{b as __pageData,u as default};
